#!/usr/bin/env python3
import sys, os, re, gzip, json, csv, io, datetime
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP
import xml.etree.ElementTree as ET

ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
FACT = {'kg': Fraction(1), 'g': Fraction(1, 1000), 'lb': Fraction('0.45359237'),
        'oz': Fraction('0.028349523125')}
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
}
DELIM = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
BASEDATE = {'east': 'ymd', 'lakeside': 'iso', 'river': 'mm/dd/yyyy', 'west': 'dd.mm.yyyy', 'harbor': 'iso'}
BASEUNIT = {'east': 'kg', 'lakeside': 'kg', 'river': 'kg', 'west': 'kg', 'harbor': 'kg'}
CODES = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
HCODES = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace'), b
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16', 'replace').lstrip('\ufeff'), b
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w\-]+)', head, re.M | re.I)
    if m:
        enc = m.group(1)
    try:
        return b.decode(enc), b
    except (LookupError, UnicodeDecodeError):
        return b.decode('utf-8', 'replace'), b


def raw_bytes(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def idnum(s):
    m = re.search(r'[Ss][Hh][^0-9]*([0-9]+)', s or '')
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'corr'
    return 'new'


def num(s, depot):
    s = s.strip()
    if depot == 'west':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(Decimal(s))


def weight_kg(s, depot, unit):
    s = s.strip()
    m = re.match(r'^([-+0-9.,]+)\s*([A-Za-z]+)$', s)
    if m:
        s, u = m.group(1), m.group(2).lower()
        if u in FACT:
            unit = u
    return num(s, depot) * FACT[unit]


def parse_date(s, form):
    s = s.strip()
    form = (form or '').strip().lower()
    if form == 'serial' or re.fullmatch(r'\d{5}', s) and form == 'serial':
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(s)))
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', s)
    if m:
        return datetime.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})', s)
    if m and form in ('iso', 'ymd', ''):
        return datetime.date(*map(int, m.groups()))
    m = re.match(r'^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$', s)
    if m:
        a, b, y = map(int, m.groups())
        if form in ('mm/dd/yyyy',):
            return datetime.date(y, a, b)
        return datetime.date(y, b, a)
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        return datetime.date(*map(int, m.groups()))
    m = re.match(r'^(\d{4})(\d{2})(\d{2})$', s)
    if m:
        return datetime.date(*map(int, m.groups()))
    raise ValueError('date ' + s)


def utc_date_time(s):
    s = s.strip()
    d = datetime.datetime.fromisoformat(s)
    if d.tzinfo is not None:
        d = d.astimezone(datetime.timezone.utc)
    return d.date()


def split_records(text, quoting):
    """Yield ('c', line) for comment lines and ('r', record_text) for rows."""
    buf = None
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if buf is None:
            if line.startswith('#'):
                yield 'c', line
                continue
            if not line.strip():
                continue
            buf = line
        else:
            buf += '\n' + line
        if not quoting or buf.count('"') % 2 == 0:
            yield 'r', buf
            buf = None
    if buf is not None:
        yield 'r', buf


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    dirs = {}
    header = None
    out = []
    for kind, item in split_records(text, delim == ','):
        if kind == 'c':
            m = re.match(r'^#\s*seq\s*=\s*(\d+)', item) or re.match(r'^#\s*[\w ]*?seq\s*[=:]\s*(\d+)', item)
            if m and seq is None:
                seq = int(m.group(1))
                continue
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*?)\s*$', item)
            if m:
                name = m.group(1).strip().lower()
                val = m.group(2).strip()
                if name == 'seq':
                    mm = re.match(r'\d+', val)
                    if mm:
                        seq = int(mm.group(0))
                else:
                    dirs[name] = val
            continue
        if delim == ',':
            row = next(csv.reader([item], delimiter=','))
        else:
            row = item.split(delim)
        low = [c.strip().lower() for c in row]
        if all(c in cols for c in low):
            header = low
            continue
        if header is None:
            continue
        rec = dict(zip(header, row))
        extra = row[len(header):]
        rowunit = None
        for e in extra:
            if e.strip().lower() in FACT:
                rowunit = e.strip().lower()
                break
        rid = rec.get('id') or rec.get('ref')
        n = idnum(rid)
        if n is None:
            continue
        t = rtype(rec.get('type') or rec.get('typ') or rec.get('kind') or rec.get('t') or rec.get('rec'))
        r = {'n': n, 't': t}
        if t != 'void':
            unit = BASEUNIT[depot]
            u = dirs.get('unit') or dirs.get('weight unit')
            if u:
                u = u.split()[0].lower()
                if u in FACT:
                    unit = u
            if rowunit:
                unit = rowunit
            wf = None
            for k in header:
                if k in ('gross', 'weight') or k.startswith('gross_'):
                    wf = k
                    break
            if wf and wf.startswith('gross_') and wf[6:] in FACT:
                unit = wf[6:]
            elif wf and '_' in wf and wf.rsplit('_', 1)[1] in FACT:
                unit = wf.rsplit('_', 1)[1]
            form = dirs.get('dates') or dirs.get('date format') or BASEDATE[depot]
            if depot == 'west':
                form = BASEDATE['west'] if not (dirs.get('dates') or dirs.get('date format')) else form
            dcol = 'date' if depot == 'harbor' else 'shipped'
            st = rec.get('status') or rec.get('state') or ''
            if depot == 'harbor':
                st = HCODES.get(st.strip().upper(), st)
            r['status'] = norm_status(st)
            r['kg'] = weight_kg(rec[wf], 'west' if depot == 'west' else depot, unit)
            r['date'] = parse_date(rec[dcol], form)
        out.append(r)
    return seq, out


FW = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), date=(10, 17), w=(17, 25), st=(25, 26), df='ydoy', unit='g'),
    'FW2': dict(len=43, id=(1, 10), type=(0, 1), date=(10, 18), w=(18, 26), st=(26, 27), df='ymd8', unit='cg'),
    'FW3': dict(len=41, id=(0, 9), type=(16, 17), date=(9, 16), w=(17, 24), st=(24, 25), df='ydoy', unit='dlb'),
}


def parse_fixed(text):
    seq = None
    cur = 'FW1'
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line:
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m and m.group(1) in FW:
                cur = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        if not line.strip() or line.startswith('SOUTH'):
            continue
        lay = FW[cur]
        if len(line) != lay['len']:
            for k, v in FW.items():
                if v['len'] == len(line):
                    lay = v
                    break
            else:
                line = line.ljust(lay['len'])
        f = lambda k: line[lay[k][0]:lay[k][1]]
        n = idnum(f('id'))
        if n is None:
            continue
        t = rtype(f('type'))
        r = {'n': n, 't': t}
        if t != 'void':
            d = f('date')
            if lay['df'] == 'ydoy':
                r['date'] = datetime.date(int(d[:4]), 1, 1) + datetime.timedelta(days=int(d[4:]) - 1)
            else:
                r['date'] = datetime.date(int(d[:4]), int(d[4:6]), int(d[6:8]))
            w = int(f('w'))
            if lay['unit'] == 'g':
                r['kg'] = Fraction(w, 1000)
            elif lay['unit'] == 'cg':
                r['kg'] = Fraction(w, 100)
            else:
                r['kg'] = Fraction(w, 10) * FACT['lb']
            r['status'] = norm_status(CODES.get(f('st').strip().upper(), f('st')))
        out.append(r)
    return seq, out


def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq', 0) or 0)
    ru = (root.get('weight-unit') or 'kg').lower()
    out = []
    for e in root.iter('shipment'):
        n = idnum(e.get('id'))
        if n is None:
            continue
        t = rtype(e.get('type'))
        r = {'n': n, 't': t}
        if t != 'void':
            def val(name):
                c = e.find(name)
                if c is not None and c.text is not None:
                    return c.text.strip()
                return e.get(name)
            w = e.find('weight')
            unit = ru
            if w is not None and w.get('unit'):
                unit = w.get('unit').lower()
            elif e.get('weight-unit'):
                unit = e.get('weight-unit').lower()
            r['kg'] = weight_kg(val('weight'), 'x', unit)
            s = val('shipped')
            if re.search(r'\d{4}-\d\d-\d\dT', s):
                r['date'] = utc_date_time(s)
            else:
                r['date'] = parse_date(s, 'iso')
            r['status'] = norm_status(val('status'))
        out.append(r)
    return seq, out


def parse_json(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            n = idnum(str(o.get('id')))
            if n is None:
                continue
            t = rtype(o.get('kind'))
            r = {'n': n, 't': t}
            if t != 'void':
                for k, val in o.items():
                    if k.startswith('weight_') and k[7:].lower() in FACT:
                        r['kg'] = Fraction(Decimal(str(val).replace(',', ''))) * FACT[k[7:].lower()]
                r['date'] = utc_date_time(o['shipped_at'])
                r['status'] = norm_status(o.get('status'))
            out.append(r)
    return seq, out


def main(data_dir, out_file):
    files = []
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0].lower()
        b = open(p, 'rb').read()
        text, _ = decode(b)
        rb = raw_bytes(b)
        if depot == 'central':
            seq, recs = parse_xml(rb)
        elif depot == 'south':
            seq, recs = parse_fixed(text)
        elif depot == 'north':
            seq, recs = parse_json(text)
        elif depot in DELIM:
            seq, recs = parse_delimited(depot, text)
        else:
            continue
        files.append((depot, seq if seq is not None else 0, name, recs))
    depots = {}
    corr = resend = 0
    state = {}
    for depot, seq, name, recs in sorted(files, key=lambda x: (x[0], x[1], x[2])):
        depots.setdefault(depot, None)
        cur = state.setdefault(depot, {})
        for r in recs:
            n = r['n']
            if r['t'] == 'new':
                if n in cur:
                    resend += 1
                else:
                    cur[n] = r
            elif r['t'] == 'corr':
                cur[n] = r
                corr += 1
            else:
                cur.pop(n, None)
                corr += 1

    def rank(d):
        return ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for d in state:
        for n in state[d]:
            owners.setdefault(n, []).append(d)
    handovers = 0
    res = {d: {'shipments': 0, 'kg': Fraction(0)} for d in state}
    months = {}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=rank)
        r = state[d][n]
        if r['status'] in ('delivered', 'delivered_late'):
            res[d]['shipments'] += 1
            res[d]['kg'] += r['kg']
            k = '%04d-%02d' % (r['date'].year, r['date'].month)
            m = months.setdefault(k, {'shipments': 0, 'kg': Fraction(0)})
            m['shipments'] += 1
            m['kg'] += r['kg']

    def rd(x):
        q = Decimal(x.numerator) / Decimal(x.denominator) if False else None
        return float((Decimal(x.numerator) * 10000000 // 1) / 1) if False else None

    def rnd(x):
        scaled = x * 100
        fl = scaled.numerator // scaled.denominator
        rem = scaled - fl
        if rem >= Fraction(1, 2):
            fl += 1
        return fl / 100
    result = {
        'depots': {d: {'shipments': res[d]['shipments'], 'total_kg': rnd(res[d]['kg'])} for d in sorted(res)},
        'months': {k: {'shipments': months[k]['shipments'], 'total_kg': rnd(months[k]['kg'])} for k in sorted(months)},
        'corrections_applied': corr,
        'resends_dropped': resend,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(result, f, indent=2)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
